{"command": "create", "path": "/app/workspace/work/ocr_cache.py", "file_text": """"Build a multi-variant OCR cache for all receipt images."""
import json
from pathlib import Path
from PIL import Image, ImageOps
import pytesseract


def ocr_variants(image_path: str):
    img = Image.open(image_path)
    gray = ImageOps.autocontrast(img.convert("L"))
    w, h = gray.size
    upscaled = ImageOps.autocontrast(
        gray.resize((w * 3, h * 3), Image.LANCZOS)
    )
    passes = [
        ("default_psm3", img, "--psm 3"),
        ("gray_autocontrast_psm6", gray, "--psm 6"),
        ("upscale_3x_psm4", upscaled, "--psm 4"),
        ("upscale_3x_psm6", upscaled, "--psm 6"),
    ]
    out = []
    for name, variant, cfg in passes:
        try:
            text = pytesseract.image_to_string(variant, config=cfg)
        except Exception:
            text = ""
        out.append({"name": name, "text": text})
    return out


def main():
    src = Path("/app/workspace/dataset/img")
    cache = {}
    for p in sorted(src.iterdir()):
        if p.suffix.lower() in {".jpg", ".jpeg", ".png", ".webp"}:
            print(f"OCR: {p.name}")
            cache[p.name] = ocr_variants(str(p))
    out_path = Path("/app/workspace/work/ocr_cache.json")
    out_path.write_text(json.dumps(cache, indent=2))
    print(f"Wrote {out_path} with {len(cache)} entries.")


if __name__ == "__main__":
    main()
