{"command": "create", "path": "/app/workspace/work/extract.py", "file_text": """"Extract date and total amount from cached multi-variant OCR output.

Pipeline:
- Load OCR cache (per-image list of variants with text).
- Extract date and total for each variant independently.
- Vote across variants per field, biased toward the most-frequent non-null
  candidate that also corroborates within a single variant.
- Write results atomically to xlsx at the end.
"""
import json
import re
from collections import Counter
from pathlib import Path

from openpyxl import Workbook


# --------------------------- Date extraction -----------------------------

# Matches DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY, DD-MM-YY, DD.MM.YYYY (also 2-digit day/month variants).
DATE_RE = re.compile(
    r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2}|\d{4})(?!\d)"
)


def _normalize_date(day: int, month: int, year: int):
    if year < 100:
        year += 2000
    if not (1 <= month <= 12 and 1 <= day <= 31 and 2000 <= year <= 2030):
        return None
    try:
        import datetime
        datetime.date(year, month, day)
    except ValueError:
        return None
    return f"{year:04d}-{month:02d}-{day:02d}"


def extract_date_candidates(text: str):
    """Return list of (score, iso_date, line_idx) candidates found in text."""
    candidates = []
    lines = text.splitlines()
    for idx, line in enumerate(lines):
        up = line.upper()
        # Priority score: lines containing "DATE" get highest priority.
        has_date_label = "DATE" in up
        # Skip lines that look like times or GST IDs.
        for m in DATE_RE.finditer(line):
            d, mo, y = int(m.group(1)), int(m.group(2)), m.group(3)
            if len(y) == 2:
                year = 2000 + int(y)
            else:
                year = int(y)
            iso = _normalize_date(d, mo, year)
            if iso is None:
                continue
            # Reject unrealistic years for receipt dataset context.
            if year < 2015 or year > 2020:
                continue
            score = 0
            if has_date_label:
                score += 10
            # Prefer 4-digit year over 2-digit for stability.
            if len(y) == 4:
                score += 1
            candidates.append((score, iso, idx))
    return candidates


def pick_date(variants):
    """Vote across variants. Returns ISO date string or None."""
    # Per variant, choose the best candidate.
    per_variant = []
    for v in variants:
        cands = extract_date_candidates(v["text"])
        if not cands:
            per_variant.append(None)
            continue
        # Prefer labelled-date, then earliest line (receipt header date).
        cands.sort(key=lambda c: (-c[0], c[2]))
        per_variant.append(cands[0][1])
    # Majority vote across variants.
    counter = Counter(x for x in per_variant if x)
    if not counter:
        return None
    # Return the most common; ties broken by first variant to find it.
    top = counter.most_common()
    best_count = top[0][1]
    winners = [d for d, c in top if c == best_count]
    for p in per_variant:
        if p in winners:
            return p
    return winners[0]


# --------------------------- Total extraction ----------------------------

# Amount pattern: integer or float, allowing commas. Does NOT allow trailing letters.
AMOUNT_RE = re.compile(r"(?<![\d.,])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)")

EXCLUSION_PREFIXES = [
    "SUBTOTAL", "SUB-TOTAL", "SUB TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "DISC",
    "CHANGE", "CASH TENDERED",
]

# Level 1: GRAND TOTAL
LVL1_RE = re.compile(r"GRAND\s*TOTAL", re.IGNORECASE)
# Level 2: TOTAL RM / TOTAL: RM (adjacent / near)
LVL2_RE = re.compile(r"TOTAL\s*:?\s*\(?\s*R[MN]\b", re.IGNORECASE)
# Level 3: TOTAL AMOUNT
LVL3_RE = re.compile(r"TOTAL\s*AMOUNT", re.IGNORECASE)
# Level 4 sub-priorities
LVL4A_RE = re.compile(r"\bNETT?\s*TOTAL\b", re.IGNORECASE)
LVL4B_RE = re.compile(r"\b(TOTAL\s*DUE|AMOUNT\s*DUE|BALANCE\s*DUE)\b", re.IGNORECASE)
LVL4C_RE = re.compile(r"\bTOTAL\b|\bAMOUNT\b", re.IGNORECASE)


def _starts_with_exclusion(line_stripped: str) -> bool:
    """Return True if the line's leading label is an exclusion keyword."""
    u = line_stripped.upper().lstrip(" .:*-|")
    for kw in EXCLUSION_PREFIXES:
        if u.startswith(kw):
            # Make sure it's a word boundary (not e.g. "SUBTOTALING" - unlikely).
            tail = u[len(kw):]
            if not tail or not tail[0].isalpha():
                return True
    return False


def _last_amount(line: str):
    """Return the last valid amount on the line as float, or None."""
    matches = list(AMOUNT_RE.finditer(line))
    for m in reversed(matches):
        s = m.group(1).replace(",", "")
        try:
            return float(s)
        except ValueError:
            continue
    return None


def _line_total_candidate(line: str, idx: int, re_pattern):
    """If line matches pattern and not excluded, return (value, idx) else None."""
    if not re_pattern.search(line):
        return None
    if _starts_with_exclusion(line):
        return None
    amt = _last_amount(line)
    if amt is None:
        return None
    return (amt, idx)


def _fallback_next_line(lines, idx):
    """If the keyword line has no amount, use the last number on next line."""
    if idx + 1 >= len(lines):
        return None
    return _last_amount(lines[idx + 1])


def extract_total_from_text(text: str):
    """Return (float_value, debug_source_level) or (None, None)."""
    lines = text.splitlines()

    # Level 1: GRAND TOTAL — pick LAST occurrence.
    hits = []
    for idx, line in enumerate(lines):
        if LVL1_RE.search(line) and not _starts_with_exclusion(line):
            amt = _last_amount(line)
            if amt is None:
                amt = _fallback_next_line(lines, idx)
            if amt is not None:
                hits.append((amt, idx))
    if hits:
        return hits[-1][0], 1

    # Level 2: TOTAL RM — pick LAST.
    hits = []
    for idx, line in enumerate(lines):
        if LVL2_RE.search(line) and not _starts_with_exclusion(line):
            amt = _last_amount(line)
            if amt is None:
                amt = _fallback_next_line(lines, idx)
            if amt is not None:
                hits.append((amt, idx))
    if hits:
        return hits[-1][0], 2

    # Level 3: TOTAL AMOUNT — pick LAST.
    hits = []
    for idx, line in enumerate(lines):
        if LVL3_RE.search(line) and not _starts_with_exclusion(line):
            amt = _last_amount(line)
            if amt is None:
                amt = _fallback_next_line(lines, idx)
            if amt is not None:
                hits.append((amt, idx))
    if hits:
        return hits[-1][0], 3

    # Level 4: sub-priority — NET TOTAL / NETT TOTAL first.
    for sub_re, sub_level in [
        (LVL4A_RE, "4a"),
        (LVL4B_RE, "4b"),
        (LVL4C_RE, "4c"),
    ]:
        hits = []
        for idx, line in enumerate(lines):
            if sub_re.search(line) and not _starts_with_exclusion(line):
                amt = _last_amount(line)
                if amt is None:
                    amt = _fallback_next_line(lines, idx)
                if amt is not None:
                    hits.append((amt, idx))
        if hits:
            return hits[-1][0], sub_level

    return None, None


def pick_total(variants):
    """Vote across variants. Return (float_value, source_variant_name) or (None, None)."""
    per_variant = []
    for v in variants:
        val, src = extract_total_from_text(v["text"])
        per_variant.append((v["name"], val, src, v["text"]))

    # Collect non-null values.
    values = [p[1] for p in per_variant if p[1] is not None]
    if not values:
        return None, None

    # Priority tiebreak: prefer value chosen at the most specific level.
    # Rank levels: 1 > 2 > 3 > 4a > 4b > 4c
    level_order = {1: 0, 2: 1, 3: 2, "4a": 3, "4b": 4, "4c": 5}
    best_level = min(level_order[p[2]] for p in per_variant if p[1] is not None)
    at_best = [p for p in per_variant if p[1] is not None and level_order[p[2]] == best_level]

    # Within best level, choose by frequency across variants.
    vals = [p[1] for p in at_best]
    c = Counter(vals)
    # Most common; tie -> first occurrence.
    best_count = c.most_common(1)[0][1]
    winners = {v for v, k in c.items() if k == best_count}
    for p in at_best:
        if p[1] in winners:
            return p[1], p[0]
    return at_best[0][1], at_best[0][0]


# ----------------------------- Writer ------------------------------------

def main():
    cache_path = Path("/app/workspace/work/ocr_cache.json")
    cache = json.loads(cache_path.read_text())

    rows = []
    debug = []
    for name in sorted(cache.keys()):
        variants = cache[name]
        date = pick_date(variants)
        total_val, src = pick_total(variants)
        if total_val is None:
            total_str = None
        else:
            total_str = f"{total_val:.2f}"
